#!/mnt/hdd01/Soft/GitHub/chen_q3_rh_clean/.venv/bin/python
"""Interval enclosure of physical source moments on [-7/10, 7/10].

This is an ephemeral diagnostic only.  It encloses the physical theta source
and its seven even derivative directions, including an n >= 9 profile-tail
envelope.  It neither reconstructs nor uses the frozen response y, and makes
no E-norm, spectral, Q-margin, or RH claim.

The finite n <= 8 part is evaluated by exact rational polynomial products and
upper incomplete gamma balls.  The gamma kernel is cached only by (s, degree);
the polynomial product is deliberately rebuilt for every ordered (n, m) pair.
"""

from __future__ import annotations

import hashlib
import json
import struct
from fractions import Fraction
from pathlib import Path
from typing import Any, Iterable

from flint import arb, ctx, fmpq, fmpq_poly


A_NUMERATOR = 7
A_DENOMINATOR = 10
TERMS = 8
MEMBER_ORDERS = (0, 2, 4, 6, 8, 10, 12)
PRECISIONS = (256, 384)
EXPECTED_Y_SHA256 = "44dda5148dad0d5940c9766afa2b2c99f786707b16ddb1749c542a1a1191969a"
EXPECTED_W_SHA256 = "0da2212a2cf7c9ac5cd627571d3e2adba14806b75cb9644028cde56bee385e7b"
SOURCE_DIAGNOSTIC = Path("/tmp/q3_source_transfer_diagnostic.json")
THETA_NORM_REFERENCE = Path("/tmp/q3_theta_norm_interval.json")
OUTPUT = Path("/tmp/q3_source_moments_interval.json")
RELATIVE_RADIUS_LIMIT = arb("1e-40")


def sha256_path(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def fail(message: str) -> None:
    raise RuntimeError(message)


def record(value: arb) -> dict[str, str]:
    """Expose the complete Arb ball, not only a rounded midpoint."""
    return {
        "ball": str(value),
        "midpoint": str(value.mid()),
        "radius": str(value.rad()),
        "lower": str(value.lower()),
        "upper": str(value.upper()),
    }


def relative_radius(value: arb) -> arb:
    scale = max(arb(1), arb(value.abs_upper()))
    return arb(value.rad()) / scale


def expand_by_absolute_error(value: arb, error: arb) -> arb:
    """Add a rigorously nonnegative absolute error without shifting the center."""
    return arb(value.mid(), value.rad() + error.abs_upper())


def require_unique_nested_mapping(value: Any, required_keys: set[str], label: str) -> dict[str, Any]:
    matches: list[dict[str, Any]] = []

    def walk(item: Any) -> None:
        if isinstance(item, dict):
            if required_keys.issubset(item):
                matches.append(item)
            for child in item.values():
                walk(child)
        elif isinstance(item, list):
            for child in item:
                walk(child)

    walk(value)
    if len(matches) != 1:
        fail(f"expected exactly one {label} mapping, found {len(matches)}")
    return matches[0]


def require_unique_value_for_key(value: Any, key: str, label: str) -> dict[str, Any]:
    matches: list[dict[str, Any]] = []

    def walk(item: Any) -> None:
        if isinstance(item, dict):
            if key in item:
                candidate = item[key]
                if not isinstance(candidate, dict):
                    fail(f"{label} is not a mapping")
                matches.append(candidate)
            for child in item.values():
                walk(child)
        elif isinstance(item, list):
            for child in item:
                walk(child)

    walk(value)
    if len(matches) != 1:
        fail(f"expected exactly one {label}, found {len(matches)}")
    return matches[0]


def metadata_bytes(entries: Any, label: str) -> bytes:
    if not isinstance(entries, list) or not entries:
        fail(f"{label} must be a nonempty metadata list")
    parts: list[bytes] = []
    for index, entry in enumerate(entries):
        if not isinstance(entry, dict):
            fail(f"{label}[{index}] is not a mapping")
        encoded = entry.get("little_endian_binary64_hex")
        if not isinstance(encoded, str):
            fail(f"{label}[{index}] lacks little_endian_binary64_hex")
        raw = bytes.fromhex(encoded)
        if len(raw) != 8:
            fail(f"{label}[{index}] is not one binary64 value")
        parts.append(raw)
    return b"".join(parts)


def binary64_entry_to_exact_arb(entry: dict[str, Any]) -> arb:
    raw = bytes.fromhex(str(entry["little_endian_binary64_hex"]))
    number = struct.unpack("<d", raw)[0]
    rational = Fraction.from_float(number)
    return arb(rational.numerator) / rational.denominator


def load_frozen_provenance() -> tuple[dict[str, Any], dict[str, Any]]:
    source = json.loads(SOURCE_DIAGNOSTIC.read_text())
    provenance = require_unique_nested_mapping(
        source,
        {"response_y_binary64", "frozen_trial_w_binary64"},
        "frozen provenance",
    )
    y_bytes = metadata_bytes(provenance["response_y_binary64"], "response_y_binary64")
    w_bytes = metadata_bytes(provenance["frozen_trial_w_binary64"], "frozen_trial_w_binary64")
    y_sha256 = hashlib.sha256(y_bytes).hexdigest()
    w_sha256 = hashlib.sha256(w_bytes).hexdigest()
    if len(y_bytes) != 7 * 8 or y_sha256 != EXPECTED_Y_SHA256:
        fail(f"frozen y identity mismatch: {y_sha256}")
    if w_sha256 != EXPECTED_W_SHA256:
        fail(f"frozen w identity mismatch: {w_sha256}")

    source_model = require_unique_value_for_key(
        source, "source_model_100dps_observed", "100-dps source-model diagnostic"
    )
    return (
        {
            "source_diagnostic_path": str(SOURCE_DIAGNOSTIC),
            "source_diagnostic_sha256": sha256_path(SOURCE_DIAGNOSTIC),
            "binary64_encoding": "little-endian IEEE-754 binary64",
            "response_y_binary64": provenance["response_y_binary64"],
            "response_y_sha256": y_sha256,
            "response_y_expected_sha256": EXPECTED_Y_SHA256,
            "response_y_identity_matches_expected": True,
            "response_y_exact_arb_values": [
                record(binary64_entry_to_exact_arb(entry))
                for entry in provenance["response_y_binary64"]
            ],
            "frozen_trial_w_sha256": w_sha256,
            "frozen_trial_w_expected_sha256": EXPECTED_W_SHA256,
            "frozen_trial_w_identity_matches_expected": True,
            "frozen_trial_w_length": len(w_bytes) // 8,
        },
        source_model,
    )


def load_theta_norm_reference() -> dict[int, dict[str, Any]]:
    reference = json.loads(THETA_NORM_REFERENCE.read_text())
    evaluations = reference.get("evaluations")
    if not isinstance(evaluations, list):
        fail("theta norm reference lacks evaluations")
    mapped: dict[int, dict[str, Any]] = {}
    for evaluation in evaluations:
        if not isinstance(evaluation, dict):
            fail("theta norm reference evaluation is not a mapping")
        bits = evaluation.get("precision_bits")
        if not isinstance(bits, int) or bits in mapped:
            fail("theta norm reference precision data are malformed")
        mapped[bits] = evaluation
    if not all(bits in mapped for bits in PRECISIONS):
        fail("theta norm reference lacks a required precision")
    return mapped


def ball_from_record(value: Any, label: str) -> arb:
    if not isinstance(value, dict):
        fail(f"{label} is not a ball record")
    serialized_ball = value.get("ball")
    if not isinstance(serialized_ball, str):
        fail(f"{label} lacks a serialized full ball")
    return arb(serialized_ball)


def polynomial_coefficients(polynomial: fmpq_poly) -> list[fmpq]:
    return list(polynomial.coeffs())


def make_derivative_polynomials(max_order: int) -> list[fmpq_poly]:
    z = fmpq_poly([0, 1])
    polynomials = [fmpq_poly([0, -3, 2])]
    for _ in range(max_order):
        current = polynomials[-1]
        next_polynomial = (fmpq(1, 2) - 2 * z) * current + 2 * z * current.derivative()
        polynomials.append(next_polynomial)
    return polynomials


def polynomial_product_for_ordered_pair(
    left: fmpq_poly, right: fmpq_poly, n_squared: int, m_squared: int
) -> list[fmpq]:
    """Rebuild S_U,V,n,m for this exact ordered pair; never cache it by s."""
    s = n_squared + m_squared
    left_coefficients = polynomial_coefficients(left)
    right_coefficients = polynomial_coefficients(right)
    product = [fmpq(0) for _ in range(len(left_coefficients) + len(right_coefficients) - 1)]
    qn = fmpq(n_squared, s)
    qm = fmpq(m_squared, s)
    for left_degree, left_coefficient in enumerate(left_coefficients):
        for right_degree, right_coefficient in enumerate(right_coefficients):
            product[left_degree + right_degree] += (
                left_coefficient
                * right_coefficient
                * qn**left_degree
                * qm**right_degree
            )
    return product


def finite_moment(
    left: fmpq_poly, right: fmpq_poly, a: arb, pi: arb, kernel_cache: dict[tuple[int, int], arb]
) -> arb:
    def gamma_kernel(s: int, degree: int) -> arb:
        key = (s, degree)
        if key not in kernel_cache:
            coefficient = pi * s
            lower = coefficient
            upper = coefficient * (2 * a).exp()
            shape = arb(degree) + arb(1) / 2
            kernel_cache[key] = coefficient ** (-arb(1) / 2) * (
                lower.gamma_upper(shape) - upper.gamma_upper(shape)
            )
        return kernel_cache[key]

    total = arb(0)
    for n in range(1, TERMS + 1):
        for m in range(1, TERMS + 1):
            n_squared, m_squared = n * n, m * m
            coefficients = polynomial_product_for_ordered_pair(
                left, right, n_squared, m_squared
            )
            s = n_squared + m_squared
            for degree, coefficient in enumerate(coefficients):
                if coefficient:
                    total += arb(coefficient) * gamma_kernel(s, degree)
    return total


def finite_profile_envelope(polynomial: fmpq_poly, a: arb, pi: arb) -> arb:
    exponential_upper = (a / 2).exp()
    e_to_2a = (2 * a).exp()
    coefficients = polynomial_coefficients(polynomial)
    total = arb(0)
    for n in range(1, TERMS + 1):
        z_upper = pi * n * n * e_to_2a
        polynomial_upper = sum(
            (arb(abs(coefficient)) * z_upper**degree for degree, coefficient in enumerate(coefficients)),
            arb(0),
        )
        total += (-pi * n * n).exp() * polynomial_upper
    return exponential_upper * total


def tail_derivative_bound(polynomial: fmpq_poly, pi: arb) -> arb:
    rho = (arb(10) / 9) ** 34 * (-19 * pi).exp()
    if not rho < 1:
        fail("tail geometric ratio did not validate")
    coefficients = polynomial_coefficients(polynomial)
    coefficient_sum = sum(
        (arb(abs(coefficient)) * (81 * pi) ** degree for degree, coefficient in enumerate(coefficients)),
        arb(0),
    )
    return (-81 * pi).exp() * coefficient_sum / (1 - rho)


def tail_product_error(a: arb, h_left: arb, b_left: arb, h_right: arb, b_right: arb) -> arb:
    return 2 * a * (h_left * b_right + h_right * b_left + b_left * b_right)


def full_moment(
    left: fmpq_poly,
    right: fmpq_poly,
    h_left: arb,
    b_left: arb,
    h_right: arb,
    b_right: arb,
    a: arb,
    pi: arb,
    kernel_cache: dict[tuple[int, int], arb],
) -> tuple[arb, dict[str, Any]]:
    finite = finite_moment(left, right, a, pi, kernel_cache)
    error = tail_product_error(a, h_left, b_left, h_right, b_right)
    full = expand_by_absolute_error(finite, error)
    return full, {
        "finite_n_le_8": record(finite),
        "absolute_profile_tail_error": record(error),
        "full_enclosure": record(full),
    }


def diagnostic_reference_by_member(source_model: dict[str, Any]) -> dict[str, dict[str, Any]]:
    directions = source_model.get("directions")
    if not isinstance(directions, list):
        fail("source-model directions are malformed")
    output: dict[str, dict[str, Any]] = {}
    for direction in directions:
        if not isinstance(direction, dict):
            fail("source-model direction is malformed")
        member = direction.get("member")
        if not isinstance(member, str) or member in output:
            fail("source-model member data are malformed")
        output[member] = direction
    expected_members = {f"g{order}" for order in MEMBER_ORDERS}
    if set(output) != expected_members:
        fail("source-model members do not match g0,...,g12")
    return output


def diagnostic_delta(value: arb, observed: Any, label: str) -> dict[str, Any]:
    if not isinstance(observed, str):
        fail(f"missing observed {label}")
    reference = arb(observed)
    return {
        "observed_n_le_8_not_an_enclosure": observed,
        "full_interval_minus_observed": record(value - reference),
    }


def one_precision(
    bits: int,
    frozen_provenance: dict[str, Any],
    source_model: dict[str, Any],
    theta_reference: dict[str, Any],
) -> tuple[dict[str, Any], tuple[arb, ...]]:
    ctx.prec = bits
    pi = arb.pi()
    a = arb(A_NUMERATOR) / A_DENOMINATOR
    polynomials = make_derivative_polynomials(14)
    directions = [
        polynomials[2 * index + 2] - fmpq(1, 4) * polynomials[2 * index]
        for index in range(len(MEMBER_ORDERS))
    ]
    h_phi = finite_profile_envelope(polynomials[0], a, pi)
    b_derivatives = [tail_derivative_bound(polynomial, pi) for polynomial in polynomials]
    b_phi = b_derivatives[0]
    h_directions = [finite_profile_envelope(polynomial, a, pi) for polynomial in directions]
    b_directions = [
        b_derivatives[2 * index + 2] + b_derivatives[2 * index] / 4
        for index in range(len(MEMBER_ORDERS))
    ]
    kernel_cache: dict[tuple[int, int], arb] = {}

    i0, i0_meta = full_moment(
        polynomials[0], polynomials[0], h_phi, b_phi, h_phi, b_phi, a, pi, kernel_cache
    )
    if not i0 > 0:
        fail("I0 is not rigorously positive")
    n_a = i0.sqrt()
    observed = diagnostic_reference_by_member(source_model)
    rows: list[dict[str, Any]] = []
    primary_balls: list[arb] = [i0, n_a]
    for index, order in enumerate(MEMBER_ORDERS):
        member = f"g{order}"
        v, v_meta = full_moment(
            polynomials[0], directions[index], h_phi, b_phi,
            h_directions[index], b_directions[index], a, pi, kernel_cache,
        )
        w, w_meta = full_moment(
            directions[index], directions[index], h_directions[index], b_directions[index],
            h_directions[index], b_directions[index], a, pi, kernel_cache,
        )
        alpha = v / i0
        rho_squared = w - v**2 / i0
        if not rho_squared > 0:
            fail(f"rho squared is not rigorously positive for {member}")
        rho = rho_squared.sqrt()
        reference_row = observed[member]
        rows.append(
            {
                "member": member,
                "v": record(v),
                "w": record(w),
                "alpha": record(alpha),
                "rho_squared": record(rho_squared),
                "rho": record(rho),
                "moment_enclosures": {"v": v_meta, "w": w_meta},
                "diagnostic_comparison_to_observed_n_le_8": {
                    "alpha": diagnostic_delta(alpha, reference_row.get("alpha_observed"), "alpha"),
                    "rho": diagnostic_delta(rho, reference_row.get("rho_observed"), "rho"),
                },
            }
        )
        primary_balls.extend([v, w, alpha, rho_squared, rho])

    reference_i0 = ball_from_record(theta_reference["inside_mass"], "reference inside_mass")
    reference_n_a = ball_from_record(theta_reference["N_a"], "reference N_a")
    relative_radii = [relative_radius(value) for value in primary_balls]
    controlled = all(radius < RELATIVE_RADIUS_LIMIT for radius in relative_radii)
    return (
        {
            "precision_bits": bits,
            "a_exact": "7/10",
            "finite_terms": TERMS,
            "I0": record(i0),
            "N_a": record(n_a),
            "I0_moment_enclosure": i0_meta,
            "profile_tail_envelopes": {
                "Phi": {"H": record(h_phi), "B": record(b_phi)},
                "directions": [
                    {
                        "member": f"g{order}",
                        "H": record(h_directions[index]),
                        "B": record(b_directions[index]),
                    }
                    for index, order in enumerate(MEMBER_ORDERS)
                ],
            },
            "rows": rows,
            "kernel_cache": {
                "policy": "K_s_d_only; S_U_V_n_m_rebuilt_per_ordered_pair",
                "entries": len(kernel_cache),
            },
            "positivity_guards_passed": True,
            "relative_radius_limit": str(RELATIVE_RADIUS_LIMIT),
            "largest_relative_radius": str(max(relative_radii)),
            "all_primary_relative_radii_below_limit": bool(controlled),
            "theta_norm_reference_diagnostic_only": {
                "source_path": str(THETA_NORM_REFERENCE),
                "source_sha256": sha256_path(THETA_NORM_REFERENCE),
                "I0_reference": record(reference_i0),
                "N_a_reference": record(reference_n_a),
                "I0_overlaps_reference": bool(i0.overlaps(reference_i0)),
                "N_a_overlaps_reference": bool(n_a.overlaps(reference_n_a)),
            },
            "frozen_y_read_only_provenance": frozen_provenance,
        },
        tuple(primary_balls),
    )


def all_overlaps(left: Iterable[arb], right: Iterable[arb]) -> bool:
    left_list, right_list = list(left), list(right)
    return len(left_list) == len(right_list) and all(
        first.overlaps(second) for first, second in zip(left_list, right_list)
    )


def main() -> int:
    original_precision = ctx.prec
    try:
        frozen_provenance, source_model = load_frozen_provenance()
        theta_reference = load_theta_norm_reference()
        evaluations: list[dict[str, Any]] = []
        primary_balls: list[tuple[arb, ...]] = []
        for bits in PRECISIONS:
            evaluation, balls = one_precision(
                bits, frozen_provenance, source_model, theta_reference[bits]
            )
            evaluations.append(evaluation)
            primary_balls.append(balls)
        precision_overlap = all_overlaps(primary_balls[0], primary_balls[1])
        reference_overlap = all(
            evaluation["theta_norm_reference_diagnostic_only"]["I0_overlaps_reference"]
            and evaluation["theta_norm_reference_diagnostic_only"]["N_a_overlaps_reference"]
            for evaluation in evaluations
        )
        controlled = all(
            evaluation["positivity_guards_passed"]
            and evaluation["all_primary_relative_radii_below_limit"]
            for evaluation in evaluations
        )
        complete = precision_overlap and controlled
        result = {
            "status": "TRUE_PHYSICAL_SOURCE_MOMENTS_ENCLOSED" if complete else "UNRESOLVED",
            "scope": "PHYSICAL_MOMENTS_ONLY_NOT_E_NORM_Q_MARGIN_EIGENVALUE_OR_RH",
            "a_exact": "7/10",
            "finite_terms": TERMS,
            "definitions": {
                "I0": "<Phi,Phi>",
                "v_j": "<Phi,g_(2j)>",
                "w_j": "<g_(2j),g_(2j)>",
                "alpha_j": "v_j/I0",
                "rho_j": "sqrt(w_j-v_j^2/I0)",
            },
            "method": {
                "finite_integral": "upper incomplete gamma K_(s,d) with n,m=1,...,8",
                "kernel_cache_policy": "cache only K_(s,d); rebuild S_(U,V,n,m) for each ordered pair",
                "tail_extension": "2a(H_U B_V + H_V B_U + B_U B_V)",
                "frozen_y": "read and hash-validated for provenance only; never recomputed or used in moment arithmetic",
            },
            "provenance": {
                "script_path": str(Path(__file__)),
                "script_sha256": sha256_path(Path(__file__)),
                "frozen_y": frozen_provenance,
            },
            "two_precision_primary_ball_overlap": precision_overlap,
            "theta_norm_reference_overlap_diagnostic_only": reference_overlap,
            "evaluations": evaluations,
            "limitations": [
                "This is an interval enclosure of physical source moments only.",
                "It does not establish a source-to-polynomial E-norm transfer.",
                "It does not establish a Q margin, eigenvalue statement, or RH claim.",
                "Observed n<=8 comparisons are diagnostics, not interval certificates.",
            ],
        }
        OUTPUT.write_text(json.dumps(result, indent=2) + "\n")
        print(f"RESULT={result['status']}", flush=True)
        print(f"TWO_PRECISION_OVERLAP={precision_overlap}", flush=True)
        for evaluation in evaluations:
            print(
                f"{evaluation['precision_bits']} I0={evaluation['I0']['ball']} "
                f"N_a={evaluation['N_a']['ball']}",
                flush=True,
            )
        return 0 if complete else 2
    except Exception as error:
        OUTPUT.write_text(json.dumps({"status": "FAILED", "error": repr(error)}, indent=2) + "\n")
        print(f"RESULT=FAILED {error!r}", flush=True)
        return 1
    finally:
        ctx.prec = original_precision


if __name__ == "__main__":
    raise SystemExit(main())
